import SwiftUI

struct CosmeticInventoryView: View {

    @ObservedObject var gamificationViewModel: GamificationViewModel

    // MARK: - Cosmetic Categories

    private enum CosmeticCategory: String, CaseIterable, Identifiable {

        case avatar
        case frame
        case theme

        var id: String {
            rawValue
        }

        var title: String {

            switch self {

            case .avatar:
                return "Avatars"

            case .frame:
                return "Frames"

            case .theme:
                return "Themes"
            }
        }
    }

    // MARK: - View State

    @State private var selectedCategory: CosmeticCategory = .avatar

    @State private var isInitialLoading = true
    
    
    // MARK: - Equipment Alert

    @State private var showEquipmentAlert = false

    @State private var equipmentAlertTitle = ""

    @State private var equipmentAlertMessage = ""


    // MARK: - Owned Cosmetic Details

    private var ownedCosmeticDetails: [CosmeticDefinition] {

        // Collect the IDs of every cosmetic the player owns
        let ownedIDs = Set(
            gamificationViewModel.ownedCosmetics.map {
                $0.cosmetic_id
            }
        )

        // Find those cosmetics in the catalog
        return gamificationViewModel.cosmeticCatalog
            .filter {
                ownedIDs.contains($0.id)
            }
            .sorted {
                $0.sort_order < $1.sort_order
            }
    }

    // MARK: - Filter by Category

    private var displayedCosmetics: [CosmeticDefinition] {

        ownedCosmeticDetails.filter {
            $0.cosmetic_type == selectedCategory.rawValue
        }
    }

    // MARK: - Main View

    var body: some View {

        ScrollView {

            VStack(alignment: .leading, spacing: 20) {

                // MARK: - Inventory Header

                VStack(alignment: .leading, spacing: 8) {

                    Text("Your Cosmetic Collection")
                        .font(.title2)
                        .fontWeight(.bold)

                    Text(
                        "View the avatars, profile frames, and themes you've unlocked."
                    )
                    .font(.subheadline)
                    .foregroundColor(.secondary)
                }

                // MARK: - Collection Summary

                GroupBox {

                    HStack(spacing: 12) {

                        Image(systemName: "shippingbox.fill")
                            .font(.title2)
                            .foregroundColor(.purple)

                        VStack(alignment: .leading, spacing: 4) {

                            Text("Cosmetics Owned")
                                .font(.subheadline)
                                .foregroundColor(.secondary)

                            Text(
                                "\(gamificationViewModel.ownedCosmetics.count)"
                            )
                            .font(.title2)
                            .fontWeight(.bold)
                        }

                        Spacer()
                    }
                    .padding(.vertical, 6)
                }

                // MARK: - Category Selection

                VStack(alignment: .leading, spacing: 12) {

                    Text("Categories")
                        .font(.headline)

                    Picker(
                        "Cosmetic Category",
                        selection: $selectedCategory
                    ) {

                        ForEach(CosmeticCategory.allCases) { category in

                            Text(category.title)
                                .tag(category)
                        }
                    }
                    .pickerStyle(.segmented)
                }

                // MARK: - Cosmetic Inventory

                if isInitialLoading ||
                    gamificationViewModel.isLoadingCosmetics {

                    HStack {

                        Spacer()

                        ProgressView("Loading your cosmetics...")

                        Spacer()
                    }
                    .padding(.vertical, 30)

                } else if let error =
                    gamificationViewModel.cosmeticError {

                    VStack(spacing: 12) {

                        Image(systemName: "exclamationmark.triangle")
                            .font(.largeTitle)
                            .foregroundColor(.orange)

                        Text(error)
                            .font(.subheadline)
                            .multilineTextAlignment(.center)

                        Button("Try Again") {

                            Task {

                                await gamificationViewModel
                                    .refreshCosmeticData()
                            }
                        }
                        .buttonStyle(.bordered)
                    }
                    .frame(maxWidth: .infinity)
                    .padding(.vertical, 30)

                } else if displayedCosmetics.isEmpty {

                    // MARK: - Empty Inventory

                    VStack(spacing: 14) {

                        Image(systemName: emptyCategoryIcon)
                            .font(.system(size: 48))
                            .foregroundColor(.secondary)

                        Text("No \(selectedCategory.title) Unlocked")
                            .font(.headline)

                        Text(
                            "Craft cosmetics in the Rewards Hub to add them to your collection."
                        )
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                        .multilineTextAlignment(.center)
                    }
                    .frame(maxWidth: .infinity)
                    .padding(.vertical, 40)

                } else {

                    // MARK: - Owned Cosmetic Cards

                    LazyVStack(spacing: 14) {

                        ForEach(displayedCosmetics) { cosmetic in

                            cosmeticCard(cosmetic)
                        }
                    }
                }

            } // Closes VStack
            .padding()

        } // Closes ScrollView

        .modifier(
            ProjectHealthThemeModifier(
                gamificationViewModel: gamificationViewModel
            )
        )

        .navigationTitle("Cosmetic Inventory")
        .navigationBarTitleDisplayMode(.inline)

        // MARK: - Load Owned Cosmetics

        .task {

            isInitialLoading = true

            await gamificationViewModel.refreshCosmeticData()

            isInitialLoading = false
        }

        // MARK: - Pull to Refresh

        .refreshable {

            await gamificationViewModel.refreshCosmeticData()
        }
        
        // MARK: - Equipment Result Alert

                .alert(
                    equipmentAlertTitle,
                    isPresented: $showEquipmentAlert
                ) {

                    Button("OK", role: .cancel) {}

                } message: {

                    Text(equipmentAlertMessage)
                }

    } // Closes body


    
    // MARK: - Cosmetic Card

    private func cosmeticCard(
        _ cosmetic: CosmeticDefinition
    ) -> some View {

        let isEquipped = gamificationViewModel.isCosmeticEquipped(
            cosmetic.id
        )

        return VStack(alignment: .leading, spacing: 14) {

            // MARK: - Cosmetic Information

            HStack(spacing: 14) {

                
                Image(cosmetic.asset_key)
                    .resizable()
                    .aspectRatio(
                        contentMode: cosmetic.cosmetic_type == "frame"
                            ? .fit
                            : .fill
                    )
                    .frame(width: 70, height: 70)
                    .background(
                        collectionColor(for: cosmetic.collection)
                            .opacity(0.12)
                    )
                    .clipShape(
                        RoundedRectangle(cornerRadius: 12)
                    )


                VStack(alignment: .leading, spacing: 6) {

                    Text(cosmetic.name)
                        .font(.headline)

                    Text(cosmetic.description)
                        .font(.caption)
                        .foregroundColor(.secondary)

                    Text("\(cosmetic.collection.capitalized) Collection")
                        .font(.caption2)
                        .foregroundColor(
                            collectionColor(for: cosmetic.collection)
                        )

                    // MARK: - Equipment Status

                    if isEquipped {

                        Label(
                            "Equipped",
                            systemImage: "checkmark.circle.fill"
                        )
                        .font(.caption)
                        .foregroundColor(.green)

                    } else {

                        Label(
                            "Owned",
                            systemImage: "checkmark.seal.fill"
                        )
                        .font(.caption)
                        .foregroundColor(.secondary)
                    }
                }

                Spacer()
            }

            Divider()

            // MARK: - Equip or Unequip Button

            Button {

                Task {

                    let succeeded: Bool

                    if isEquipped {

                        // Remove this cosmetic from its slot
                        succeeded = await gamificationViewModel
                            .unequipCosmetic(
                                slot: cosmetic.cosmetic_type
                            )

                    } else {

                        // Equip this owned cosmetic
                        succeeded = await gamificationViewModel
                            .equipCosmetic(cosmetic)
                    }

                    // MARK: - Show Equipment Result

                    if succeeded {

                        equipmentAlertTitle = isEquipped
                            ? "Cosmetic Unequipped"
                            : "Cosmetic Equipped"

                        equipmentAlertMessage =
                            gamificationViewModel.cosmeticEquipmentNotice
                            ?? "Your equipment has been updated."

                    } else {

                        equipmentAlertTitle = "Unable to Update Equipment"

                        equipmentAlertMessage =
                            gamificationViewModel.cosmeticEquipmentError
                            ?? "Please try again."
                    }

                    showEquipmentAlert = true
                }

            } label: {

                HStack(spacing: 8) {

                    if gamificationViewModel.isChangingEquipment {

                        ProgressView()

                    } else {

                        Image(
                            systemName: isEquipped
                                ? "xmark.circle"
                                : "checkmark.circle"
                        )
                    }

                    Text(isEquipped ? "Unequip" : "Equip")
                        .fontWeight(.semibold)
                }
                .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .disabled(
                gamificationViewModel.isChangingEquipment
            )

        } // Closes VStack
        .padding()
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color(.secondarySystemGroupedBackground))
        .cornerRadius(16)

    } // Closes cosmeticCard()



    // MARK: - Empty Category Icon

    private var emptyCategoryIcon: String {

        switch selectedCategory {

        case .avatar:
            return "person.crop.circle"

        case .frame:
            return "square.dashed"

        case .theme:
            return "paintpalette"
        }
    }


    // MARK: - Collection Colors

    private func collectionColor(
        for collection: String
    ) -> Color {

        switch collection {

        case "astral":
            return .purple

        case "nature":
            return .green

        case "cyber":
            return .cyan

        default:
            return .secondary
        }
    }

} // Closes CosmeticInventoryView


